describe('Form Autocomplete Attribute Tests', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should set correct autocomplete attribute on input fields', () => {
    // Intercept the API call for autocomplete suggestions
    cy.intercept('GET', '/api/autocomplete/search*').as('getAutocomplete');

    // Fill in the first input field
    cy.get('[data-testid="first-name-input"]').type('John');
    cy.get('[data-testid="first-name-input"]').should('have.attr', 'autocomplete', 'name');

    // Fill in the second input field
    cy.get('[data-testid="last-name-input"]').type('Doe');
    cy.get('[data-testid="last-name-input"]').should('have.attr', 'autocomplete', 'name');

    // Verify the API was called with the correct query
    cy.wait('@getAutocomplete').then((interception) => {
      expect(interception.response.body.length).to.be.greaterThan(0);
    });

    // Verify the autocomplete attribute is set for both fields
    cy.get('[data-testid="first-name-input"]').should('have.attr', 'autocomplete', 'name');
    cy.get('[data-testid="last-name-input"]').should('have.attr', 'autocomplete', 'name');
  });

  it('should handle edge case when autocomplete is disabled', () => {
    // Intercept the API call for autocomplete suggestions
    cy.intercept('GET', '/api/autocomplete/search*').as('getAutocomplete');

    // Fill in a disabled input field
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');

    // Verify the autocomplete attribute is not set on a disabled field
    cy.get('[data-testid="email-input"]').should('not.have.attr', 'autocomplete');

    // Verify the API was not called for the disabled field
    cy.wait('@getAutocomplete').then((interception) => {
      expect(interception.response.body.length).to.equal(0);
    });

    // Verify the form still submits without autocomplete interference
    cy.get('[data-testid="submit-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
